		if _, ok := booleanOperators[operator]; !ok {
			return nil, ErrInvalidf("constraint operator %q is not valid for type boolean", r.Operator)
		}
	default:
		return nil, ErrInvalidf("invalid constraint type: %q", r.Type.String())
	}

