447	func matchesNumber(c constraint, v string) (bool, error) {
448		switch strings.ToLower(c.Operator) {
449		case opNotPresent:
450			return len(strings.TrimSpace(v)) == 0, nil
451		case opPresent:
452			return len(strings.TrimSpace(v)) != 0, nil
453		}
454	
455		// can't parse an empty string
456		if strings.TrimSpace(v) == "" {
457			return false, nil
458		}
459	
460		n, err := strconv.ParseFloat(strings.TrimSpace(v), 64)
461		if err != nil || math.IsNaN(n) || math.IsInf(n, 0) {
462			return false, fmt.Errorf("parsing number from %q", v)
463		}
464	
465		value, err := strconv.ParseFloat(strings.TrimSpace(c.Value), 64)
466		if err != nil || math.IsNaN(value) || math.IsInf(value, 0) {
467			return false, fmt.Errorf("parsing number from %q", c.Value)
468		}
469	
470		switch strings.ToLower(c.Operator) {
471		case opEQ:
472			return value == n, nil
473		case opNEQ:
474			return value != n, nil
475		case opLT:
476			return n < value, nil
477		case opLTE:
478			return n <= value, nil
479		case opGT:
480			return n > value, nil
481		case opGTE:
482			return n >= value, nil
483		}
484	
485		return false, nil
486	}
